let freightContext=null;
function freightForRow(r){if(freightContext)return PurchaseFreight.rowAmount(r,freightContext);const rows=typeof planningRows==='function'?planningRows():ROWS;return PurchaseFreight.rowAmount(r,PurchaseFreight.rates(rows,CONTAINERS))}
/* Product freight follows row volume multiplied by its container rate. */
try{const prefs=JSON.parse(sessionStorage.getItem('purchase:freight:v1')||'{}');CONTAINERS.forEach(c=>Object.assign(c,prefs[c.id]||{freightMode:'formula',freightBase:202000000,freightCapacity:170}))}catch{}
function mockFreightSave(id,changes){const c=contById(Number(id));if(!c)return;const before=PurchaseFreight.calculate(c,contStats(c.id).m3);if(changes.freight!=null&&(PurchaseCalculations.number(changes.freight)==null||changes.freight<0)||changes.freightBase!=null&&(PurchaseCalculations.number(changes.freightBase)==null||changes.freightBase<0)||changes.freightCapacity!=null&&(PurchaseCalculations.number(changes.freightCapacity)==null||changes.freightCapacity<=0)){toast('Cước không được âm; m³ chuẩn phải lớn hơn 0.',true);renderConts();return}Object.assign(c,changes);logIt({action:'container_edit',contName:c.name,summary:'Sửa cước cont',detail:[{label:'Cước',old:JSON.stringify(before),new:JSON.stringify(PurchaseFreight.calculate(c,contStats(c.id).m3))}]});try{sessionStorage.setItem('purchase:freight:v1',JSON.stringify(Object.fromEntries(CONTAINERS.map(x=>[x.id,{freightMode:x.freightMode||'formula',freightBase:x.freightBase??202000000,freightCapacity:x.freightCapacity??170,freight:x.freight}]))))}catch{}render()}
rateOf=function(id){const c=contById(id);return c?PurchaseFreight.calculate(c,contStats(id).m3).rate:202000000/170};
const freightRender=renderConts;renderConts=function(){freightRender();contFull.querySelectorAll('tr.cont-pick').forEach(tr=>{const id=Number(tr.getAttribute('onclick')?.match(/pickCont\('([0-9]+)'\)/)?.[1]),c=contById(id);if(!c){if(id===0){const estimate=PurchaseFreight.calculate({freightMode:'formula'},contStats(null).m3);tr.cells[5].innerHTML=nf(estimate.amount)+'<small style="display:block;color:var(--muted)">Tạm tính</small>';tr.cells[6].textContent=nf(estimate.rate)}return}const f=PurchaseFreight.calculate(c,contStats(id).m3);tr.cells[5].innerHTML='<input class="cell-input" data-cont-freight="'+id+'" type="text" inputmode="decimal" aria-label="Tiền VC '+pe(c.name)+'" value="'+nf(f.amount)+'" style="width:110px;max-width:100%;text-align:right"><small style="display:block;color:var(--muted)">'+(f.mode==='formula'?'Tự tính':'Nhập tay')+'</small><details><summary style="font-size:10px;cursor:pointer">Công thức</summary><label>Tiền chuẩn<input data-freight-base="'+id+'" value="'+f.base+'" style="width:100px"></label><label>m³ chuẩn<input data-freight-capacity="'+id+'" value="'+f.capacity+'" style="width:60px"></label><button data-freight-auto="'+id+'" class="ghost">Dùng tự tính</button></details>';tr.cells[6].innerHTML=nf(f.rate);tr.cells[5].onclick=e=>e.stopPropagation()})};
contFull.addEventListener('change',e=>{const d=e.target.dataset;if(d.contFreight&&e.target.value.trim()===''){mockFreightSave(d.contFreight,{freight:null,freightMode:'formula',freightBase:202000000,freightCapacity:170});return}if(e.target.value?.trim()===''){toast('Nhập số hợp lệ.',true);renderConts();return}const raw=PurchaseCalculations.parse(e.target.value);if(d.contFreight)mockFreightSave(d.contFreight,{freight:raw,freightMode:'manual'});if(d.freightBase)mockFreightSave(d.freightBase,{freightBase:raw,freightMode:'formula'});if(d.freightCapacity)mockFreightSave(d.freightCapacity,{freightCapacity:raw,freightMode:'formula'})});
contFull.addEventListener('click',e=>{const id=e.target.closest('[data-freight-auto]')?.dataset.freightAuto;if(id){e.stopPropagation();mockFreightSave(id,{freightMode:'formula'})}});
renderConts();

for(const [id,d] of bulkDrafts){delete d.changes.freightAmount;delete d.before.freightAmount;if(!Object.keys(d.changes).length)bulkDrafts.delete(id)}

function withFreightContext(fn,args){const previous=freightContext;if(!previous)freightContext=PurchaseFreight.rates(planningRows(),CONTAINERS);try{return fn(...args)}finally{freightContext=previous}}
const formulaRender=render;render=function(...args){return withFreightContext(formulaRender,args)};const formulaRenderConts=renderConts;renderConts=function(...args){return withFreightContext(formulaRenderConts,args)};
render();
